"""Keep the combined ranking and the match-only diagnostics visibly distinct."""
from pathlib import Path
p=Path(__file__).resolve().parents[2]/'outputs'/'manager-elo.html'
s=p.read_text(encoding='utf-8')
s=s.replace('<select id="sort" aria-label="Sort ranking">','<select id="sort" aria-label="Sort ranking"><option value="score">Combined rating</option>')
s=s.replace('<th>Total impact</th>','<th>Combined rating</th><th>Trophy bonus</th><th>Elo impact</th>')
s=s.replace("['impact','Period impact']","['score','Combined rating'],['trophy_bonus','Trophy bonus'],['impact','Elo impact']")
s=s.replace('${cell(r.impact)}','${cell(r.score)}${cell(r.trophy_bonus)}${cell(r.impact)}')
s=s.replace('return {...r,impact:points.length?',"const trophies=(r.trophies||[]).filter(t=>t.award_date>=start&&t.award_date<=end);\n      const trophy_bonus=Number(trophies.reduce((n,t)=>n+t.half_bonus,0).toFixed(2));\n      const score=points.length||trophies.length?Number((Number(sum.toFixed(1))+trophy_bonus).toFixed(2)):null;\n      return {...r,trophies,trophy_bonus,score,impact:points.length?")
s=s.replace('Table impact, per-38 rate, match count, club count and graph use','Combined rating includes Elo impact and half-strength trophy bonuses awarded in the selected period. Elo impact, per-38 rate, match count, club count and graph use')
s=s.replace('Graph totals restart at zero.','The graph shows match-only Elo and restarts at zero; trophy bonuses are not plotted.')
s=s.replace('Selected-period impact: ${num(r.impact)} across ${r.matches} matches.','Combined rating: ${num(r.score)} = ${num(r.impact)} match Elo + ${num(r.trophy_bonus)} trophy bonus across ${r.matches} matches.')
s=s.replace('<h2>Compare manager trajectories</h2>','<h2>Compare match-only Elo trajectories</h2>')
note='''<p id="rating-model-note"><b>Combined rating = match Elo impact + half-strength trophy bonus.</b> UCL and league titles carry different weights, adjusted by precompetition club Elo. Trophy points are shown separately; per-38, last-12-month figures and the graph measure match Elo only. <a href="#trophy-method">How the bonus works</a>.</p>'''
s=s.replace('<p id="shown"',note+'<p id="shown"',1)
method='''<section id="trophy-method"><h2>Half-strength trophy bonuses</h2><p>Adopted 31 October 2026. The combined rating adds a trophy component to corrected match Elo impact. Full base points: Champions League 80; Premier League 50; La Liga and Serie A 40; Bundesliga 30; Ligue 1 and Europa League 25; Conference League 10. We use <b>half</b> those values, multiplied by a difficulty factor between 0.25 and 2.</p><p>Bonus = 0.5 × base × clamp(1 − Elo gap / 200, 0.25, 2). The gap is the winner’s club Elo minus its strongest rival’s Elo before the domestic season or European main stage begins. This is an uncalibrated strength proxy, not historical bookmaker title odds or squad valuation. It can underestimate dominant clubs’ resource advantages. No clubs receive name-based exemptions.</p><p>The ledger covers 75 titles from 2016/17 to 2025/26. Domestic titles are assigned to the reviewed season-end head coach and dated to the club’s final league appearance, not the earlier clinching date. European trophies are assigned to the winning final’s coach, including wins after extra time or penalties. There is no shared predecessor credit. Date filters include only awards inside the selected period. Titles before July 2016, including Luis Enrique’s 2015 Champions League win, are outside the window.</p><p>This composite recognises achievement but partly rewards success already present in match results. It is not pure Elo, a causal estimate, or a validated prediction. Match Elo, per-38, recent form, trajectories and the local community preview remain match-based. The JSON download includes each manager’s trophy ledger and individual bonuses. Historical fixture corrections are retained in its audit trail.</p></section>'''
s=s.replace('<summary>Method, coverage and limitations</summary>','<summary>Method, coverage and limitations</summary>'+method)
assert 'id="trophy-method"' in s and "['score','Combined rating']" in s and 'trophies,trophy_bonus,score,impact:' in s
p.write_text(s,encoding='utf-8')
